css:
body{margin:0;background:#070B1B}
*{box-sizing:border-box}
.apw{--bg:#FFFFFF;--bg2:#F6F4EF;--bg3:#E4EEF8;--card:#FFFFFF;--ink:#0E1430;--ink2:#3E4668;--mute:#4A5272;--line:#E2DDD2;--field:#8A91B0;--accent:#FF4A1C;--accent-hi:#FF6B42;--accent-ink:#0E1430;--accent-text:#B02A08;--accent-soft:#FFE1D6;--ok:#1E7A52;--ok-soft:#E3F1EA;--band:#0A0F24;--band2:#111936;--shadow:0 14px 34px rgba(10,15,36,.14);font-family:"Schibsted Grotesk",ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility}
.apw.dark{--bg:#0A0F24;--bg2:#0E1530;--bg3:#101A38;--card:#141D3D;--ink:#F6F4EF;--ink2:#D5DAF0;--mute:#AEB5D8;--line:rgba(255,255,255,.13);--field:#6B7398;--accent-text:#FF8A66;--accent-soft:rgba(255,74,28,.16);--ok:#4CC38A;--ok-soft:rgba(76,195,138,.15);--band:#070B1B;--band2:#111936;--shadow:0 14px 34px rgba(0,0,0,.45)}
.apw a{color:var(--accent-text)}
.mono{font-family:"IBM Plex Mono",ui-monospace,Consolas,monospace}
.wm{font-family:"Archivo","Arial Black",sans-serif;font-weight:800;text-transform:uppercase;letter-spacing:.045em;line-height:1}
.eb{margin:0;font-family:"IBM Plex Mono",ui-monospace,Consolas,monospace;font-size:13px;font-weight:600;letter-spacing:.09em;text-transform:uppercase;color:var(--accent-text)}
.h1{margin:0;font-weight:800;letter-spacing:-.05em;line-height:.95;text-wrap:balance}
.h2{margin:10px 0 0;font-size:34px;font-weight:800;letter-spacing:-.045em;line-height:1;text-wrap:balance}
.lead{margin:12px 0 0;font-size:17px;line-height:1.55;color:var(--ink2)}
.btn{display:flex;align-items:center;justify-content:center;gap:10px;min-height:56px;padding:0 24px;border-radius:999px;border:1.6px solid transparent;font:inherit;font-size:18px;font-weight:700;line-height:1;cursor:pointer;text-decoration:none;white-space:nowrap}
.btn:disabled{opacity:.45;cursor:not-allowed}
.apw .btn-dot{background:var(--accent);color:var(--accent-ink)}.apw .btn-dot:hover{background:var(--accent-hi);color:var(--accent-ink)}
.apw .btn-ink{background:var(--ink);color:var(--bg)}
.apw .btn-line{background:transparent;color:var(--ink);border-color:var(--field)}
.apw .btn-line-n{background:transparent;color:#FFFFFF;border-color:rgba(255,255,255,.3)}
.apw .btn-pay{background:#000000;color:#FFFFFF;border-color:#000000}
.apw.dark .btn-pay{border-color:rgba(255,255,255,.4)}
.ibtn{width:48px;height:48px;flex:0 0 48px;display:grid;place-items:center;border-radius:50%;border:1.6px solid var(--line);background:transparent;color:var(--ink);cursor:pointer;padding:0;text-decoration:none}
.apw .ibtn-n{border-color:rgba(255,255,255,.24);color:#F6F4EF}
.ldot{display:inline-block;width:9px;height:9px;flex:0 0 9px;border-radius:50%;background:#FF4A1C;animation:apwBlink 1.6s ease-out infinite}
details>summary{list-style:none;cursor:pointer}details>summary::-webkit-details-marker{display:none}
.chev{transition:transform .2s ease}details[open]>summary .chev{transform:rotate(45deg)}
@keyframes apwBlink{0%{box-shadow:0 0 0 0 rgba(255,74,28,.6)}70%{box-shadow:0 0 0 8px rgba(255,74,28,0)}100%{box-shadow:0 0 0 0 rgba(255,74,28,0)}}
@media (prefers-reduced-motion:reduce){.ldot{animation:none}}
input:focus-visible,button:focus-visible,a:focus-visible,summary:focus-visible,textarea:focus-visible,ul:focus-visible{outline:3px solid #FF6B42;outline-offset:2px}
.apw .flab{display:block;margin-top:16px;font-size:15px;font-weight:700}
.apw .fin{display:block;width:100%;height:54px;margin-top:6px;padding:0 16px;border-radius:14px;border:1.6px solid var(--field);background:var(--card);color:var(--ink);font:inherit;font-size:17px}
.apw textarea.fin{height:96px;padding:12px 16px;line-height:1.45;resize:vertical}
.apw .ferr{margin:8px 0 0;font-size:14px;font-weight:700;color:var(--accent-text)}
.apw .cbx{display:flex;gap:12px;align-items:flex-start;margin-top:10px;padding:14px;border-radius:16px;border:1.6px solid var(--field);background:var(--card);cursor:pointer}
.apw .cbx input{width:24px;height:24px;flex:0 0 24px;margin:1px 0 0;accent-color:#FF4A1C}
.apw .cbx b{display:block;font-size:16px;line-height:1.3}
.apw .cbx small{display:block;margin-top:3px;font-size:14px;line-height:1.45;color:var(--mute)}
.apw .fine{margin:12px 0 0;font-size:13px;line-height:1.55;color:var(--mute)}
.apw .fine a,.apw .tlink{color:var(--ink);font-weight:700}
.apw .tlink{display:inline-flex;align-items:center;min-height:44px;padding:0;border:0;background:none;font:inherit;font-size:16px;cursor:pointer;text-decoration:underline;text-underline-offset:3px}
.apw .ycard{margin-top:18px;border-radius:20px;border:1px solid var(--line);background:var(--card);overflow:hidden}
.apw .yrow{display:flex;justify-content:space-between;gap:12px;padding:14px 16px;border-bottom:1px solid var(--line);font-size:15px}
.apw .yrow:last-child{border-bottom:0}
.apw .yrow span{color:var(--mute)}.apw .yrow b{text-align:right}
.apw .yh2{margin:36px 0 0;font-size:24px;font-weight:800;letter-spacing:-.035em;line-height:1.1}
.apw .note{display:flex;gap:12px;align-items:flex-start;margin-top:14px;padding:14px 16px;border-radius:16px;background:var(--bg2);font-size:15px;line-height:1.5;color:var(--ink2)}
.apw .demo{display:inline-flex;align-items:center;gap:8px;margin-top:14px;padding:6px 12px;border-radius:999px;background:var(--bg2);border:1px dashed var(--field);font-size:13px;font-weight:700;color:var(--mute)}
.apw .hdr{position:sticky;top:0;z-index:20;background:var(--bg);border-bottom:1px solid var(--line)}
.apw .hin{display:flex;align-items:center;gap:8px;max-width:1240px;height:80px;margin:0 auto;padding:0 12px 0 14px}
.apw .hlogo{display:flex;align-items:center;flex:0 0 auto;min-height:48px;text-decoration:none}
.apw .lgo{display:block;width:auto;height:67px}
.apw .hsp{flex:1}
.apw .dnav,.apw .hbook{display:none}
@media (min-width:1024px){
.apw .hin{max-width:1224px;height:88px;padding:0 32px;gap:10px}
.apw .lgo{height:73px}
.apw .dnav{display:flex;align-items:center;gap:2px;margin-left:20px}
.apw .dnav a{display:inline-flex;align-items:center;min-height:44px;padding:0 12px;border-radius:999px;color:var(--ink);font-size:16px;font-weight:600;text-decoration:none;white-space:nowrap}
.apw .dnav a:hover{background:var(--bg2)}
.apw .hbook{display:inline-flex;min-height:48px;padding:0 22px;font-size:16px}
.apw .mbtn{display:none}
}
@media (min-width:1024px) and (max-width:1199px){.apw .lgo{height:67px}}
@media (min-width:1024px) and (max-width:1279px){.apw .dnav{margin-left:6px}.apw .dnav a{padding:0 9px;font-size:15px}}
.apw .accm{width:100%;max-width:560px;margin:0 auto;padding:26px 20px 64px}
@media (min-width:1024px){.apw .accm{padding:64px 20px 104px}}
.apw .afoot{display:flex;flex-wrap:wrap;justify-content:center;padding:24px 20px 40px;background:#070B1B}
.apw .afoot a{display:inline-flex;align-items:center;min-height:44px;margin-right:18px;color:#D5DAF0;font-size:15px;text-decoration:none}

script:
class Component extends DCLogic {
  constructor(props) {
    super(props);
    this.state = { dark: this._themeFromProps(), phase: 'loading', email: '', code: '', err: '', busy: false, me: null, form: {}, saved: false, saveErr: '', portalErr: '' };
  }
  componentDidMount() { this._themeInit(); this._load(); }
  componentWillUnmount() { this._themeStop(); }
  _themeFromProps() {
    const pt = this.props.theme || 'light';
    if (pt === 'dark') return true;
    if (pt === 'auto' && typeof window !== 'undefined' && window.matchMedia) return window.matchMedia('(prefers-color-scheme: dark)').matches;
    return false;
  }
  _themeInit() {
    if (typeof window === 'undefined' || !window.matchMedia) return;
    this._mq = window.matchMedia('(prefers-color-scheme: dark)');
    this._mqf = () => { if ((this.props.theme || 'light') === 'auto') this.setState({ dark: this._mq.matches }); };
    if (this._mq.addEventListener) this._mq.addEventListener('change', this._mqf);
  }
  _themeStop() {
    if (this._mq && this._mq.removeEventListener) this._mq.removeEventListener('change', this._mqf);
  }
  componentDidUpdate(prev) {
    if (prev.theme !== this.props.theme) this.setState({ dark: this._themeFromProps() });
  }
  _themeVals() {
    const d = !!this.state.dark;
    return {
      themeClass: d ? 'dark' : 'light',
      isDark: d,
      isLight: !d,
      themeLabel: d ? 'Switch to the light look' : 'Switch to the dark look',
      themeMenuLabel: d ? 'Light look' : 'Dark look',
      toggleTheme: () => this.setState({ dark: !this.state.dark })
    };
  }
  _price(id, dogs) {
    const base = { week: 108, twice: 189, eow: 75 };
    const extra = { week: 13, twice: 13, eow: 9 };
    return base[id] + Math.max(0, dogs - 2) * extra[id];
  }
  _per(id, dogs) {
    const visits = { week: 52 / 12, twice: 104 / 12, eow: 26 / 12 };
    return Math.round(this._price(id, dogs) / visits[id]);
  }
  _cal(id, onBand) {
    const out = [];
    for (let i = 0; i < 28; i++) {
      const d = i % 7;
      const w = Math.floor(i / 7);
      const on = id === 'week' ? d === 2 : id === 'twice' ? (d === 2 || d === 5) : (d === 2 && w % 2 === 0);
      out.push({ bg: on ? '#FF4A1C' : (onBand ? 'rgba(255,255,255,.16)' : 'var(--line)') });
    }
    return out;
  }
  _plans(onBand) {
    const s = this.state;
    const names = { week: 'Every week', twice: 'Twice a week', eow: 'Every other week' };
    return ['week', 'twice', 'eow'].map((id) => {
      const on = s.plan === id;
      return {
        id: id,
        name: names[id],
        price: '$' + this._price(id, s.dogs),
        per: 'About $' + this._per(id, s.dogs) + ' a visit',
        on: on,
        pick: () => this.setState({ plan: id }),
        aria: names[id] + ', $' + this._price(id, s.dogs) + ' a month',
        cal: this._cal(id, onBand),
        border: on ? '#FF4A1C' : (onBand ? 'rgba(255,255,255,.18)' : 'var(--field)'),
        bg: on ? 'rgba(255,74,28,.12)' : 'transparent',
        ring: on ? '#FF4A1C' : (onBand ? '#AEB5D8' : 'var(--mute)'),
        dot: on ? '#FF4A1C' : 'transparent'
      };
    });
  }
  _apw() { return typeof window !== 'undefined' ? window.APW || null : null; }
  _demo() { const a = this._apw(); return !a || !a.live; }
  _sample() {
    return { name: 'Sample Customer', email: 'you@email.com', phone: '6233096104', address: '123 W Main St', zip: '85396', plan: 'week', dogs: 2, first_visit: '2026-11-20', status: 'trialing', gate_code: '', gate_notes: '', dog_names: '', problem_spots: '', skip_spray: false, texts_visit: true, texts_deals: false };
  }
  async _load() {
    const a = this._apw();
    if (this._demo()) {
      let signed = false;
      try { signed = sessionStorage.getItem('apw.demoIn') === '1'; } catch (e) { }
      if (signed) this._setMe(this._sample()); else this.setState({ phase: 'out' });
      return;
    }
    if (!a.auth.session()) { this.setState({ phase: 'out' }); return; }
    try {
      const r = await a.get('/api/me', true);
      this._setMe(r.customer || { email: a.auth.session().email, status: 'new' });
    } catch (e) {
      if (e && e.status === 401) { a.auth.signOut(); this.setState({ phase: 'out' }); return; }
      this.setState({ phase: 'out', err: a.msg(e) });
    }
  }
  _setMe(me) {
    this.setState({ phase: 'in', me: me, busy: false, err: '', form: {
      gate: me.gate_code || '', notes: me.gate_notes || '', dogNames: me.dog_names || '', spots: me.problem_spots || '',
      noSpray: !!me.skip_spray, txtVisit: !!me.texts_visit, txtDeals: !!me.texts_deals } });
  }
  async _send() {
    const a = this._apw();
    const email = this.state.email.trim();
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) { this.setState({ err: 'Type your email, like you@email.com.' }); return; }
    const a0 = this._apw();
    if (a0 && a0.closed) { this.setState({ err: 'My Yard opens soon. Questions? Call or text 623.309.6104.' }); return; }
    if (this._demo()) { this.setState({ phase: 'code', code: '', err: '' }); return; }
    this.setState({ busy: true, err: '' });
    try { await a.auth.sendCode(email); this.setState({ busy: false, phase: 'code', code: '' }); }
    catch (e) { this.setState({ busy: false, err: a.msg(e) }); }
  }
  async _verify() {
    const a = this._apw();
    const code = String(this.state.code || '').replace(/\D/g, '');
    if (code.length !== 6) { this.setState({ err: 'Type the 6 numbers from the email.' }); return; }
    if (this._demo()) {
      try { sessionStorage.setItem('apw.demoIn', '1'); } catch (e) { }
      this._setMe(Object.assign(this._sample(), { email: this.state.email.trim() }));
      return;
    }
    this.setState({ busy: true, err: '' });
    try { await a.auth.verifyCode(this.state.email.trim(), code); this.setState({ phase: 'loading', busy: false }); this._load(); }
    catch (e) { this.setState({ busy: false, err: 'That code did not work. Check the email and try again, or send a new code.' }); }
  }
  async _save() {
    const a = this._apw();
    const f = this.state.form;
    if (this._demo()) { this.setState({ saved: true, saveErr: '' }); return; }
    this.setState({ busy: true, saveErr: '', saved: false });
    try {
      const r = await a.post('/api/me', { gate_code: f.gate, gate_notes: f.notes, dog_names: f.dogNames, problem_spots: f.spots, skip_spray: !!f.noSpray, texts_visit: !!f.txtVisit, texts_deals: !!f.txtDeals }, true);
      this.setState({ busy: false, saved: true, me: r.customer || this.state.me });
    } catch (e) { this.setState({ busy: false, saveErr: a.msg(e) }); }
  }
  async _portal() {
    const a = this._apw();
    if (this._demo()) { this.setState({ portalErr: 'Demo mode: this opens your Stripe billing page once Stripe is connected.' }); return; }
    this.setState({ busy: true, portalErr: '' });
    try { const r = await a.post('/api/portal', {}, true); location.href = r.url; }
    catch (e) { this.setState({ busy: false, portalErr: a.msg(e) }); }
  }
  _signOut() {
    const a = this._apw();
    if (a && a.auth) a.auth.signOut();
    try { sessionStorage.removeItem('apw.demoIn'); } catch (e) { }
    this.setState({ phase: 'out', me: null, code: '', err: '' });
  }
  _sms(text) { return 'sms:+16233096104?&body=' + encodeURIComponent(text); }
  renderVals() {
    const s = this.state;
    const me = s.me || {};
    const f = s.form || {};
    const names = { week: 'Every week', twice: 'Twice a week', eow: 'Every other week' };
    const statuses = { trialing: 'Free month', active: 'Active', past_due: 'Card problem', canceled: 'Canceled', paused: 'Paused', checkout: 'Not finished', new: 'Not finished', unpaid: 'Card problem' };
    const towns = { '85326': 'Buckeye, AZ 85326', '85396': 'Buckeye, AZ 85396', '85338': 'Goodyear, AZ 85338', '85395': 'Goodyear, AZ 85395', '85340': 'Litchfield Park, AZ 85340', '85355': 'Waddell, AZ 85355' };
    const day = me.first_visit ? new Date(me.first_visit + 'T12:00:00') : null;
    const set = (k, fromCheck) => (e) => { const nf = Object.assign({}, this.state.form); nf[k] = fromCheck ? !!e.target.checked : e.target.value; this.setState({ form: nf, saved: false }); };
    const ph = String(me.phone || '').replace(/\D/g, '');
    const first = String(me.name || '').trim().split(/\s+/)[0] || 'there';
    return Object.assign({}, this._themeVals(), {
      loading: s.phase === 'loading',
      showOut: s.phase === 'out',
      showCode: s.phase === 'code',
      showIn: s.phase === 'in',
      isDemo: this._demo(),
      email: s.email,
      onEmail: (e) => this.setState({ email: e.target.value, err: '' }),
      enterSend: (e) => { if (e.key === 'Enter') { e.preventDefault(); this._send(); } },
      send: () => this._send(),
      sendLabel: s.busy ? 'Sending…' : 'Send my code',
      code: s.code,
      onCode: (e) => { const v = String(e.target.value || '').replace(/\D/g, '').slice(0, 6); this.setState({ code: v, err: '' }); if (v.length === 6) setTimeout(() => this._verify(), 60); },
      enterCode: (e) => { if (e.key === 'Enter') { e.preventDefault(); this._verify(); } },
      verify: () => this._verify(),
      verifyLabel: s.busy ? 'Checking…' : 'Sign in',
      changeEmail: () => this.setState({ phase: 'out', code: '', err: '' }),
      err: s.err,
      busy: s.busy,
      first: first,
      planLine: me.plan ? names[me.plan] + ' · ' + (me.dogs === 1 ? '1 dog' : (me.dogs || 2) + ' dogs') : 'No plan yet',
      priceLine: me.plan ? '$' + this._price(me.plan, me.dogs || 2) + ' a month' : 'Free first month',
      firstLine: day ? day.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' }) : 'We reach out to set it',
      statusLine: statuses[me.status] || 'Not finished',
      addrLine: me.address ? me.address + ', ' + (towns[me.zip] || 'AZ') : 'Not added yet',
      needsFinish: !me.status || me.status === 'new' || me.status === 'checkout',
      phoneLine: ph.length === 10 ? ph.slice(0, 3) + '.' + ph.slice(3, 6) + '.' + ph.slice(6) : 'your mobile number',
      gate: f.gate || '', onGate: set('gate'),
      notes: f.notes || '', onNotes: set('notes'),
      dogNames: f.dogNames || '', onDogNames: set('dogNames'),
      spots: f.spots || '', onSpots: set('spots'),
      noSpray: !!f.noSpray, onNoSpray: set('noSpray', true),
      txtVisit: !!f.txtVisit, onTxtVisit: set('txtVisit', true),
      txtDeals: !!f.txtDeals, onTxtDeals: set('txtDeals', true),
      save: () => this._save(),
      saveLabel: s.busy ? 'Saving…' : (s.saved ? 'Saved' : 'Save my yard'),
      saveErr: s.saveErr,
      skipHref: this._sms('Hi! Please skip my next visit. My address is ' + (me.address || '') + '.'),
      pauseHref: this._sms('Hi! Please pause my visits. My address is ' + (me.address || '') + '. Start again on: '),
      portal: () => this._portal(),
      portalErr: s.portalErr,
      signOut: () => this._signOut()
    });
  }
}
